param([string]$CliPath=(Resolve-Path 'XuanYu.Editor.Control.Cli/bin/Debug/net10.0/XuanYu.Editor.Control.Cli.exe').Path,[string]$AppPath=(Resolve-Path 'XuanYu.Editor.App/bin/Debug/net10.0/XuanYu.Editor.App.exe').Path)
$ErrorActionPreference='Stop'
$dir=Join-Path (Get-Location) 'docs/qa/XYC-P2-A-R1/evidence/silent-smoke';New-Item -ItemType Directory -Force -Path $dir|Out-Null
$cli=$CliPath;$app=$AppPath;$session=[Guid]::NewGuid().ToString('N')
$si=[Diagnostics.ProcessStartInfo]::new($cli);$si.UseShellExecute=$false;$si.RedirectStandardInput=$true;$si.RedirectStandardOutput=$true;$si.ArgumentList.Add('--app');$si.ArgumentList.Add($app);$si.ArgumentList.Add('--xyc-silent');$si.ArgumentList.Add('--session-id');$si.ArgumentList.Add($session);$si.ArgumentList.Add('--timeout-seconds');$si.ArgumentList.Add('90')
$p=[Diagnostics.Process]::new();$p.StartInfo=$si;$rows=[Collections.Generic.List[object]]::new();function Send([string]$command){$q=@{schemaVersion='XYC-API/1';requestId=[Guid]::NewGuid().ToString('N');sessionId=$session;command=$command;args=@{}};$p.StandardInput.WriteLine(($q|ConvertTo-Json -Compress -Depth 8));$r=$p.StandardOutput.ReadLine()|ConvertFrom-Json -Depth 20;$rows.Add($r);if(!$r.success){throw "$command failed: $($r.errorCode)"};return $r}
try{$null=$p.Start();$runtime=Send 'runtime.info';$scene=Send 'scene.inspect';$camera=Send 'camera.inspect';$null=Send 'session.close';$p.StandardInput.Close();if(!$p.WaitForExit(15000)){throw 'silent host did not exit'};$hashes=@($app,[IO.Path]::ChangeExtension($app,'.dll'),(Join-Path (Split-Path $app) 'XuanYu.Editor.UI.dll'))|%{[pscustomobject]@{path=$_;sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $_).Hash}};[pscustomobject]@{sessionId=$session;runtime=$runtime.observedState;scene=$scene.observedState;camera=$camera.observedState;exitCode=$p.ExitCode;buildHashes=$hashes;commands=$rows}|ConvertTo-Json -Depth 25|Set-Content -LiteralPath (Join-Path $dir 'silent-smoke.json') -Encoding utf8}catch{if(!$p.HasExited){try{$p.Kill($true);$p.WaitForExit()}catch{}};throw}finally{$p.Dispose()}
